        layoutTestDpi=0;services::ActivateLanguage(language,error);check(!host.IsWindowVisible(),"own editor fixtures do not display a user-facing host");DWORD pid=0;GetWindowThreadProcessId(GetForegroundWindow(),&pid);check(GetForegroundWindow()==foreground||pid!=GetCurrentProcessId(),"native fixtures do not take user foreground");Idle(page);page->DestroyWindow();page=nullptr;host.DestroyWindow();AfxGetApp()->m_pMainWnd=prior;
